/bin/bash -c "python3 - <<'PY'
from pypdf import PdfReader
reader=PdfReader('manuscript.pdf')
links=set()
for n,p in enumerate(reader.pages,1):
    for a in p.get('/Annots',[]):
        d=a.get_object().get('/A',{})
        if d.get('/URI'):
            uri=str(d['/URI'])
            if any(s in uri.lower() for s in ['github','gitlab','code','osf','zenodo','huggingface','moralfoundations']):
                links.add((n,uri))
print('\\n'.join(f'Page {n}: {uri}' for n,uri in sorted(links)) or 'No matching artifact or questionnaire links in PDF annotations.')
PY"
